          .justifyContent(FlexAlign.Center)
          .border({ width: TOK_BORDER_W, color: readerAppColor('TOK_BORDER', this.appThemeScheme) })
          .borderRadius(22)
          .onClick((): void => this.onClose());
        }
        .width('100%')
        .padding({ top: 20, bottom: 20 });
      }
      .width('100%')
      .padding({ left: 20, right: 20, top: 20 });
    }

